function drawPlayer(){const x=state.x*TILE+20,y=state.y*TILE+22;ctx.fillStyle='#435e4144';ctx.beginPath();ctx.ellipse(x,y+12,12,5,0,0,6.3);ctx.fill();ctx.fillStyle='#e8bd93';ctx.beginPath();ctx.arc(x,y-7,6,0,6.3);ctx.fill();ctx.fillStyle='#415b50';ctx.beginPath();ctx.arc(x,y-10,7,Math.PI,0);ctx.lineTo(x+6,y-8);ctx.lineTo(x-6,y-8);ctx.fill();ctx.fillStyle='#df8e68';ctx.beginPath();ctx.roundRect(x-8,y-1,16,15,5);ctx.fill();ctx.fillStyle='#f4e8cc';ctx.beginPath();ctx.moveTo(x-7,y);ctx.lineTo(x,y+8);ctx.lineTo(x+7,y);ctx.lineTo(x,y+12);ctx.closePath();ctx.fill();ctx.fillStyle='#486654';ctx.fillRect(x-6,y+13,5,6);ctx.fillRect(x+2,y+13,5,6);ctx.fillStyle='#f3dfaa';ctx.beginPath();ctx.arc(x+9,y-9,3,0,6.3);ctx.fill()}
function updateUI(){
