  $('partyCount').textContent=state.party.length;$('capsuleCount').textContent=`× ${state.capsules}`;$('potionCount').textContent=`× ${state.potions}`;$('coins').textContent=state.coins;$('coords').textContent=`${state.x}, ${state.y}`;
  $('questProgressBar').style.width=`${Math.min(100,state.captured/2*100)}%`;$('questProgressText').textContent=`${Math.min(2,state.captured)} / 2`;
  $('questTitle').textContent=state.questDone?'숲의 작은 영웅':'첫 번째 친구';$('questSub').textContent=state.questDone?'루미가 고마워하고 있어요':'몬스터 두 마리를 포획해 주세요';
  $('questProgressBar').style.background=state.questDone?'#d4ad58':'#82a66b';$('bagCount').textContent=`${state.capsules+state.potions} items`;
}
function activeMon(){return state.party.find(m=>m.hp>0)||state.party[0]}
function getBlocked(x,y){if(x<1||x>=COLS-1||y<1||y>=ROWS-1)return true;if(isPond(x,y))return true;return treeSpots.some(([tx,ty])=>tx===x&&ty===y&&!isPath(tx,ty))}
function nearNpc(){return Math.abs(state.x-12)+Math.abs(state.y-3)<=1}
function move(dx,dy){if(battle||!$('dialogue').classList.contains('hidden')||busy)return;const now=Date.now();if(now-lastMove<105)return;lastMove=now;const nx=state.x+dx,ny=state.y+dy;if(getBlocked(nx,ny))return;state.x=nx;state.y=ny;state.steps++;$('interactionPrompt').classList.toggle('show',nearNpc());$('interactionPrompt').textContent=nearNpc()?'SPACE · 루미와 대화하기':'';if(isTallGrass(nx,ny)&&Math.random()<.24){save();renderCanvas();updateUI();startBattle();return}if(state.steps%5===0&&Math.random()<.14)toast('풀숲이 살랑거려요…');save();renderCanvas();updateUI();$('worldTip').innerHTML=nearNpc()?'<b>SPACE</b>를 눌러 루미와 이야기해 보세요.':'키보드 <b>WASD</b> 또는 방향키로 움직여 보세요.'}
function interact(){if(battle||busy)return;if(nearNpc()){talkToNpc();return}toast('루미에게 가까이 다가가서 SPACE를 눌러 보세요.')}
function openDialogue(lines,onDone){dialogueQueue=lines.slice();dialogueDone=onDone||null;showDialogueLine()}
function showDialogueLine(){const box=$('dialogue');if(!dialogueQueue.length){box.classList.add('hidden');if(dialogueDone){const fn=dialogueDone;dialogueDone=null;fn()}return}const line=dialogueQueue.shift();$('dialogueName').textContent=line.name||'루미 연구원';$('dialogueAvatar').textContent=line.avatar||'✦';$('dialogueText').textContent=line.text;box.classList.remove('hidden')}
function talkToNpc(){
  $('interactionPrompt').classList.remove('show');
  if(state.questDone){openDialogue([{text:'두 친구가 서로를 얼마나 아끼는지 알게 됐어. 네 덕분에 숲의 기록이 한층 따뜻해졌어.'},{text:'잠깐 쉬어 갈래? 다친 친구들을 돌봐 줄게.'}],()=>{state.party.forEach(m=>m.hp=m.maxHp);save();updateUI();renderCanvas();toast('파티의 HP가 모두 회복됐어요!')});return}
