  const remaining=2-state.captured;
  if(state.captured===0)openDialogue([{text:'안녕, 탐험가! 나는 루미야. 초원에 사는 친구들을 도감에 기록하고 있어.'},{text:'풀숲에서 야생 몬스터를 만나면 약하게 만든 뒤 포획 캡슐을 던져 봐. 두 친구를 데려오면 멋진 보상을 줄게!'}]);
  else openDialogue([{text:`벌써 ${state.captured}마리나 친구가 생겼네! ${remaining}마리만 더 만나서 함께 돌아와 줘.`},{text:'파티가 지쳤다면 숲의 물약을 사용하거나, 의뢰를 마치고 내게 돌아와. 회복시켜 줄게!'}]);
}
function startBattle(){const keys=['sprout','ember','dew','acorn'];const key=keys[Math.floor(Math.random()*keys.length)];const s=species[key],level=2+Math.floor(Math.random()*3);battle={species:key,name:s.name,level,maxHp:s.hp+2*(level-2),hp:s.hp+2*(level-2),atk:s.atk+Math.floor((level-2)/2)};busy=false;const layer=$('combatLayer');layer.classList.remove('hidden');$('battleMessage').textContent=`야생 ${s.name}이(가) 풀숲에서 나타났다!`;updateBattle();renderCanvas();}
function updateBattle(){if(!battle)return;const enemy=species[battle.species],mon=activeMon(),ps=species[mon.species];$('enemyName').textContent=battle.name;$('enemyLevel').textContent=`Lv. ${battle.level}`;$('enemyHpText').textContent=`${battle.hp} / ${battle.maxHp}`;$('enemyHpBar').style.width=`${clamp(battle.hp/battle.maxHp*100,0,100)}%`;$('playerName').textContent=mon.name;$('playerLevel').textContent=`Lv. ${mon.level}`;$('playerHpText').textContent=`${mon.hp} / ${mon.maxHp}`;$('playerHpBar').style.width=`${hpPercent(mon)}%`;$('playerHpBar').style.background=mon.hp/mon.maxHp<.25?'#d77b61':'#75a781';$('enemyArt').innerHTML=drawCreature(battle.species,142);$('playerArt').innerHTML=drawCreature(mon.species,126);$('battleTurn').textContent=busy?'ENEMY TURN':'YOUR TURN';renderBattleActions()}
function renderBattleActions(){const box=$('battleActions');box.innerHTML='';if(!battle)return;const mon=activeMon(),s=species[mon.species];const actions=[['공격','기본 공격',()=>playerAction('attack'),false],['기술',s.skill,()=>playerAction('skill'),false],['포획','캡슐 '+state.capsules,()=>playerAction('capture'),state.capsules<=0||state.party.length>=4],['도망','안전하게 후퇴',()=>playerAction('run'),false]];actions.forEach(([title,sub,fn,disabled],i)=>{const b=document.createElement('button');b.className=`battle-action ${i===2?'capture':''} ${i===3?'run':''}`;b.disabled=busy||disabled;b.innerHTML=`${title}<span>${disabled&&i===2?(state.party.length>=4?'파티가 가득 찼어요':'캡슐 없음'):sub}</span>`;b.addEventListener('click',fn);box.appendChild(b)})}
