  if(action==='attack'||action==='skill'){const isSkill=action==='skill';let damage=Math.max(2,Math.floor((isSkill?ally.skillDmg:ally.atk+2)+mon.level*.45));const mult=typeEffect(ally.type,foe.type);damage=Math.floor(damage*mult);battle.hp=Math.max(0,battle.hp-damage);$('battleMessage').textContent=`${mon.name}의 ${isSkill?ally.skill:'공격'}! ${foe.name}에게 ${damage}의 피해를 줬다.${mult>1?' 효과가 뛰어났다!':mult<1?' 별로 효과가 없다…':''}`;updateBattle();if(battle.hp<=0){setTimeout(victory,700);return}setTimeout(enemyTurn,850);return}
  if(action==='capture'){state.capsules--;const chance=clamp(.27+(1-battle.hp/battle.maxHp)*.5+(ally.type===foe.type?.08:0),.12,.88);save();updateUI();if(Math.random()<chance){const caught={id:'mon-'+Date.now(),species:battle.species,name:battle.name,level:battle.level,hp:Math.ceil(battle.maxHp*.7),maxHp:battle.maxHp,xp:0};state.party.push(caught);state.captured++;const extra=state.captured===2&&!state.questDone?' 루미에게 돌아가 보상을 받자!':'';$('battleMessage').textContent=`포획 성공! ${battle.name}이(가) 파티에 합류했다.${extra}`;updateBattle();updateUI();save();setTimeout(()=>{endBattle();questToast(`${battle.name}이(가) 새로운 친구가 되었어요!`)},1100);return}$('battleMessage').textContent=`앗, ${battle.name}이(가) 캡슐에서 빠져나왔다!`;updateBattle();setTimeout(enemyTurn,850);return}
