  function usePotion(){if(battle){toast('전투 중에는 기술 메뉴에서 물약을 사용할 수 없어요.');return}if(state.potions<=0){toast('숲의 물약이 없어요.');return}const target=state.party.filter(m=>m.hp<m.maxHp).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(!target){toast('파티의 HP가 모두 가득해요!');return}const before=target.hp;target.hp=Math.min(target.maxHp,target.hp+20);state.potions--;save();updateUI();toast(`${target.name}의 HP가 ${before}에서 ${target.hp}로 회복됐어요!`)}
  function showModal(content){$('modalCard').innerHTML=content;$('modalBackdrop').classList.remove('hidden');const close=$('modalCard').querySelector('.modal-close');if(close)close.addEventListener('click',hideModal);const primary=$('modalCard').querySelector('.modal-primary');if(primary)primary.addEventListener('click',hideModal)}
  function hideModal(){$('modalBackdrop').classList.add('hidden')}
  function openParty(){const rows=state.party.map(m=>{const s=species[m.species];return `<div class="modal-party-item"><div class="mon-avatar">${drawCreature(m.species,43)}</div><div class="member-info"><div class="member-name">${m.name}<span class="type-tag ${s.kind}">${s.type}</span></div><div class="member-level">레벨 ${m.level} · 경험치 ${m.xp}/10</div></div><div class="modal-stats"><span>HP <b>${m.hp}/${m.maxHp}</b></span></div></div>`}).join('');showModal(`<button class="modal-close" aria-label="닫기">×</button><span class="modal-eyebrow">FIELD TEAM</span><h2>함께하는 친구들</h2><p class="modal-intro">모험을 함께하는 파티예요. 물약은 가방에서 사용할 수 있어요.</p><div class="modal-party-list">${rows}</div><button class="modal-primary">좋아요</button>`)}
  function openHelp(){showModal(`<button class="modal-close" aria-label="닫기">×</button><span class="modal-eyebrow">FIELD GUIDE</span><h2>모험 안내서</h2><p class="modal-intro">이끼숲에서 친구를 만나고, 함께 성장해 보세요.</p><ul class="help-list"><li><b>이동</b><span>WASD 또는 방향키. 모바일에서는 화면의 방향 패드를 사용해요.</span></li><li><b>대화</b><span>루미 연구원 곁에서 SPACE 또는 E를 눌러요.</span></li><li><b>포획</b><span>풀숲에서 야생 몬스터를 만나요. HP를 낮춘 뒤 포획 캡슐을 던지면 성공률이 올라가요.</span></li><li><b>상성</b><span>불은 풀에, 풀은 물에, 물은 불에 강해요. 기술을 잘 골라 보세요!</span></li><li><b>회복</b><span>탐험 가방의 숲의 물약을 누르면 HP가 낮은 친구를 회복해요. 루미도 파티를 회복해 줘요.</span></li><li><b>의뢰</b><span>몬스터 두 마리를 포획한 뒤 루미에게 돌아가 보상을 받아요.</span></li></ul><button class="modal-primary">모험 계속하기</button>`)}
  function resetConfirm(){showModal(`<button class="modal-close" aria-label="닫기">×</button><span class="modal-eyebrow">START A NEW JOURNEY</span><h2>새 모험을 시작할까요?</h2><p class="modal-intro">저장된 파티와 진행 상황이 모두 초기화돼요. 이 작업은 되돌릴 수 없어요.</p><div class="confirm-actions"><button id="cancelReset">계속 모험하기</button><button class="danger" id="confirmReset">처음부터 시작</button></div>`);$('cancelReset').addEventListener('click',hideModal);$('confirmReset').addEventListener('click',()=>{localStorage.removeItem(saveKey);state=freshState();hideModal();updateUI();renderCanvas();toast('새 모험을 시작합니다. 루미에게 말을 걸어 보세요!')})}
  document.addEventListener('keydown',e=>{if(!$('modalBackdrop').classList.contains('hidden')){if(e.key==='Escape')hideModal();return}if(!$('dialogue').classList.contains('hidden')){if(e.key===' '||e.key==='Enter'||e.key==='e'||e.key==='E'){e.preventDefault();showDialogueLine()}return}if(battle)return;const key=e.key.toLowerCase();const dirs={arrowup:[0,-1],w:[0,-1],arrowdown:[0,1],s:[0,1],arrowleft:[-1,0],a:[-1,0],arrowright:[1,0],d:[1,0]};if(dirs[key]){e.preventDefault();move(...dirs[key]);return}if(key===' '||key==='e'||key==='enter'){e.preventDefault();interact()}});
  $('dialogueNext').addEventListener('click',showDialogueLine);$('partyDetails').addEventListener('click',openParty);$('helpBtn').addEventListener('click',openHelp);$('resetGame').addEventListener('click',resetConfirm);
  $('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))hideModal()});
  document.querySelector('.potion-icon').closest('.item-row').addEventListener('click',usePotion);
  document.querySelector('.potion-icon').closest('.item-row').style.cursor='pointer';
  document.querySelector('.capsule-icon').closest('.item-row').addEventListener('click',()=>toast(battle?'전투에서 포획 캡슐을 선택해 사용하세요.':'野생 몬스터를 만나면 포획 캡슐을 사용할 수 있어요.'));
  let muted=true;$('soundToggle').addEventListener('click',()=>{muted=!muted;$('soundToggle').classList.toggle('active',!muted);$('soundToggle').setAttribute('aria-label',muted?'소리 켜기':'소리 끄기');toast(muted?'소리가 꺼졌어요.':'숲의 소리를 켰어요.')});
  const padButtons=document.querySelectorAll('.mobile-pad button');let padTimer=null;const padDirs={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};
  padButtons.forEach(button=>{const start=e=>{e.preventDefault();const [dx,dy]=padDirs[button.dataset.dir];move(dx,dy);clearInterval(padTimer);padTimer=setInterval(()=>move(dx,dy),165)};const stop=()=>{clearInterval(padTimer);padTimer=null};button.addEventListener('pointerdown',start);button.addEventListener('pointerup',stop);button.addEventListener('pointerleave',stop);button.addEventListener('pointercancel',stop)});
  updateUI();renderCanvas();$('interactionPrompt').textContent='SPACE · 루미와 대화하기';
})();

